using System.Buffers;
using Lokad.Utf8Regex.Internal.FrontEnd;

namespace Lokad.Utf8Regex.PythonRe;

public sealed partial class Utf8PythonRegex
{
    /// <summary>Finds a named capture number from a strict UTF-8 name without allocating a key string.</summary>
    /// <param name="nameUtf8">The complete strict UTF-8 name, compared ordinally without normalization.</param>
    /// <param name="number">The validated capture number on success, or zero when undefined.</param>
    /// <param name="cancellationToken">Observed during validation and bounded lookup work.</param>
    /// <remarks>Numeric strings are not named captures. Funded expressions retain program admission during access and reject calls after close. This explicit metadata operation is independent of matching timeouts/numeric limits.</remarks>
    public bool TryGetGroupNumber(ReadOnlySpan<byte> nameUtf8, out int number,
        CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        using var programUse = EnterProgramUse();
        Utf8PatternMetadata.ValidateName(nameUtf8, cancellationToken);
        number = 0;
        for (var index = 0; index < _nameEntriesUtf8.Length; index++)
            if (Utf8PatternMetadata.NameEquals(_nameEntriesUtf8[index], nameUtf8, cancellationToken))
            { number = _nameEntries[index].Number; return true; }
        cancellationToken.ThrowIfCancellationRequested();
        return false;
    }

    /// <summary>Copies the original pattern as strict UTF-8 into caller-owned storage.</summary>
    /// <param name="destination">Receives the complete original source on success.</param>
    /// <param name="bytesRequired">The complete UTF-8 length on Done or DestinationTooSmall; zero on InvalidData.</param>
    /// <param name="cancellationToken">Observed synchronously at bounded copy/conversion checkpoints.</param>
    /// <returns>Done, DestinationTooSmall, or InvalidData for an unrepresentable legacy UTF-16 source.</returns>
    /// <remarks>No source string or buffer is allocated or retained; funded access uses the existing managed program-use lease. InvalidData and DestinationTooSmall leave the destination unchanged; cancellation may leave a partial copy. Funded expressions retain program admission during the call and reject calls after close. This explicit metadata operation uses the supplied token independently of matching timeouts and numeric invocation budgets.</remarks>
    public OperationStatus TryCopyPatternUtf8(Span<byte> destination, out int bytesRequired,
        CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        using var programUse = EnterProgramUse();
        return Utf8PatternMetadata.TryCopy(_patternSource is string text ? new Utf8ConstructionPattern(text)
            : new Utf8ConstructionPattern((byte[])_patternSource), destination, out bytesRequired, cancellationToken);
    }
}

using Lokad.Utf8Regex.Internal.Execution;

namespace Lokad.Utf8Regex.PythonRe;

/// <summary>Persistent scalar discovery for hosts that retain a cursor across calls.</summary>
public sealed partial class Utf8PythonRegex
{
    /// <summary>Creates an incremental cursor over one unchanged, well-formed UTF-8 memory subject.</summary>
    /// <remarks>The memory and its manager must remain valid until exhaustion or disposal. Returned snapshots own their values.</remarks>
    public Utf8PythonMatchCursor CreateMatchCursor(ReadOnlyMemory<byte> input)
        => CreateMatchCursor(input, 0, CancellationToken.None);

    /// <summary>Creates an incremental cursor beginning at a scalar-aligned byte offset.</summary>
    /// <exception cref="ArgumentOutOfRangeException">The byte offset is outside the subject or inside a scalar.</exception>
    public Utf8PythonMatchCursor CreateMatchCursor(ReadOnlyMemory<byte> input, int startOffsetInBytes)
        => CreateMatchCursor(input, startOffsetInBytes, CancellationToken.None);

    /// <summary>Creates an incremental cursor retaining one cumulative invocation token and deadline.</summary>
    /// <remarks>Funded expressions use their program account for temporary working/result staging. Work and result capacity are cumulative through validation, moves and snapshots. Depth bounds live backtracking/continuation frames; working bounds modeled major active capacity and growth overlap. Exclusive scratch releases synchronously; result traffic is never refunded. Sequential advances may cross asynchronous host waits.</remarks>
    /// <exception cref="OperationCanceledException">The invocation token is canceled.</exception>
    /// <exception cref="ArgumentOutOfRangeException">The byte offset is outside the subject or inside a scalar.</exception>
    /// <exception cref="ArgumentException">The subject is malformed UTF-8.</exception>
    public Utf8PythonMatchCursor CreateMatchCursor(ReadOnlyMemory<byte> input, int startOffsetInBytes,
        CancellationToken cancellationToken)
    {
        cancellationToken.ThrowIfCancellationRequested();
        var programUse = EnterProgramUse();
        try
        {
            var invocation = CreateInvocation(cancellationToken);
            ValidateScalarStartOffset(input.Span, startOffsetInBytes);
            return new Utf8PythonMatchCursor(input, ScalarProgram,
                _nameEntries, startOffsetInBytes, MatchTimeout, this, invocation, _utf8Regex, programUse);
        }
        catch { programUse?.Dispose(); throw; }
    }

    /// <summary>Creates a cursor whose modeled active working storage is funded by a caller-owned allowance.</summary>
    /// <remarks>This explicitly selects the working allowance, overriding a funded expression's default for this cursor; program/cache storage keeps its own account. Existing numeric limits, creation token and deadline still apply. Reservations precede covered buffer acquisition and include growth overlap; EOF, failure and disposal refund exclusive scratch synchronously. Result arrays are funded until publication; caller retention, input/program/cache storage and incidental objects remain outside this working scope. No result-traffic cap is implied.</remarks>
    /// <exception cref="Utf8MemoryAdmissionException">The shared allowance refused storage; no uncapped retry is performed.</exception>
    public Utf8PythonMatchCursor CreateMatchCursor(ReadOnlyMemory<byte> input, int startOffsetInBytes,
        CancellationToken cancellationToken, IUtf8MemoryAllowance workingMemoryAllowance)
    {
        cancellationToken.ThrowIfCancellationRequested();
        ArgumentNullException.ThrowIfNull(workingMemoryAllowance);
        var programUse = EnterProgramUse();
        try
        {
            var invocation = new Utf8SliceInvocation(InvocationLimits, MatchTimeout, cancellationToken, workingMemoryAllowance);
            ValidateScalarStartOffset(input.Span, startOffsetInBytes);
            return new Utf8PythonMatchCursor(input, ScalarProgram,
                _nameEntries, startOffsetInBytes, MatchTimeout, this, invocation, _utf8Regex, programUse);
        }
        catch { programUse?.Dispose(); throw; }
    }
}
